INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_BASQUE_PAGAN','Basque Pre-Christian Period',-500,1000),
 ('PER_SAMI_TRADITIONAL','Sámi Traditional / Pre-Christian',-500,1700),
 ('PER_HUNGARIAN_PAGAN','Pre-Christian Magyar Period',-500,1000)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_SAXO_GESTA','primary text','Saxo Grammaticus, Gesta Danorum (c. 1200) — the West-Slavic temple cults of Rügen','Slavic'),
 ('SRC_HELMOLD_CHRONICA','primary text','Helmold of Bosau, Chronica Slavorum (c. 1170) — the Polabian and Pomeranian Slavic gods','Slavic'),
 ('SRC_BARANDIARAN','secondary scholarship','José Miguel de Barandiarán, Mitología Vasca','Basque'),
 ('SRC_SAMI_RELIGION','secondary scholarship','Scholarship on the pre-Christian Sámi noaidi religion (e.g. Bäckman & Hultkrantz)','Sámi'),
 ('SRC_HUNGARIAN_MYTH','secondary scholarship','Scholarly reconstruction of pre-Christian Magyar religion (e.g. Róheim; Diószegi)','Hungarian')
INSERT INTO _e VALUES
 ('ENT_SLAV_PANTHEON','The Slavic Pantheon','Slavic','Collective','Pantheon','pantheon; gods; Slavic religion','A','Collective grouping the principal deities of the Slavs known from the East-Slavic Primary Chronicle and the West-Slavic temple cults of Arkona, Szczecin, and Rethra.'),
 ('ENT_SLAV_FOLK_SPIRITS','Slavic Domestic and Nature Spirits','Slavic','Collective','Spirit collective','household; nature; folk belief; tutelary spirits','A','Collective of lower mythological beings of East-Slavic folk belief (house, water, forest, and field spirits) documented in the ethnographic record.'),
 ('ENT_SLAV_SVETOVIT','Svetovit','Slavic','god','War / oracular deity','war; prophecy; harvest; sovereignty; fertility','A','The four-headed chief god of the great temple at Arkona on Rügen, whose white-horse oracle Saxo Grammaticus describes before the temple''s destruction in 1168.'),
 ('ENT_SLAV_TRIGLAV','Triglav','Slavic','god','Tripartite deity','sovereignty; three realms; prophecy; oaths','A','The three-headed god of Szczecin and Wolin whose heads signified rule over heaven, earth, and the underworld, reported in the Lives of Otto of Bamberg.'),
 ('ENT_SLAV_RUGIEVIT','Rugievit','Slavic','god','War deity','war; protection; sovereignty of Rügen','A','A seven-faced war god of the Rani at Charenza (Garz) on Rügen, whose oaken idol Saxo describes being destroyed in 1168.'),
 ('ENT_SLAV_POREVIT','Porevit','Slavic','god','Rugian deity','protection; war; tutelary cult of the Rani','B','A five-headed god of the Rani worshipped alongside Rugievit at Charenza on Rügen, known only from Saxo; his specific functions are unrecorded.'),
 ('ENT_SLAV_PORENUT','Porenut','Slavic','god','Rugian deity','protection; tutelary cult of the Rani','B','A god of the Rani at Charenza on Rügen described by Saxo as having four faces with a fifth on his chest; his functions are unrecorded.'),
 ('ENT_SLAV_YAROVIT','Yarovit','Slavic','god','War / fertility deity','war; fertility; springtime growth','A','A West-Slavic war god (Latinized Gerovitus) worshipped at Wolgast and Havelberg, equated with Mars and associated with spring fertility.'),
 ('ENT_SLAV_RADEGAST','Radegast','Slavic','god','Tribal cult deity','war; hospitality; tribal sovereignty; fire','B','The chief god of the Redarii at the temple of Rethra, named by Helmold and Adam of Bremen; often identified by scholars with Svarozhich.'),
 ('ENT_SLAV_ZHIVA','Zhiva','Slavic','goddess','Life / fertility goddess','life; fertility; vegetation','B','A goddess of the Polabian Slavs (Siwa/Živa) named by Helmold, her name connected to the Slavic root for ''living'', suggesting a life/fertility function.'),
 ('ENT_SLAV_CHERNOBOG','Chernobog','Slavic','god','Malefic deity','misfortune; darkness; evil; the underworld','B','The ''black god'' of the Polabian Slavs to whom Helmold says misfortune was attributed; the only securely attested member of the often-cited black/white dualism.'),
 ('ENT_SLAV_BELOBOG','Belobog','Slavic','god','Reconstructed deity','good fortune; light; benevolence','C','RECONSTRUCTED: the ''white god'' posited as a benevolent counterpart to Chernobog; not attested in any medieval source, a scholarly/toponymic inference.'),
 ('ENT_SLAV_SVAROZHICH','Svarozhich','Slavic','god','Fire deity','fire; sacrificial fire; the hearth','A','A fire god understood as the son of Svarog; chief deity of the temple at Rethra in the West-Slavic chronicles and the personified sacred fire in East-Slavic homilies.'),
 ('ENT_SLAV_ROZHANITSY','The Rozhanitsy','Slavic','Collective','Fate goddesses','birth; fate; destiny; childbirth','B','Female birth-and-fate spirits invoked together with Rod, repeatedly condemned in medieval East-Slavic anti-pagan homilies for childbirth offerings.'),
 ('ENT_SLAV_DOLA','Dola','Slavic','spirit','Fate spirit','fate; fortune; personal destiny','B','The personification of an individual''s allotted fate or fortune in Slavic folk belief, attached at birth; its negative counterpart is Nedola.'),
 ('ENT_SLAV_MARZANNA','Marzanna','Slavic','goddess','Death / winter goddess','death; winter; the dying and reborn year','B','Goddess or personification of death and winter (Morana/Morena), whose effigy is ritually drowned or burned at winter''s end in Slavic seasonal custom.'),
 ('ENT_SLAV_JARILO','Jarilo','Slavic','god','Fertility / vegetation deity','spring; fertility; vegetation; war','B','A spring fertility figure of the seasonal folk cult whose effigy was carried and ritually ''buried'', reconstructed as the dying-and-rising counterpart to Marzanna.'),
 ('ENT_SLAV_KUPALA','Kupala','Slavic','spirit','Seasonal personification','midsummer; water; fire; fertility','B','The personification of the midsummer (St John''s Eve) festival of fire and water; treated in some sources as a folk personification of the rite.'),
 ('ENT_SLAV_LADA','Lada','Slavic','goddess','Disputed deity','love; marriage; harmony; spring','C','DISPUTED: a putative goddess of love and marriage; Brückner and later scholarship argue she is a personification mistakenly derived from a wedding-song refrain (''lado'').'),
 ('ENT_SLAV_DEVANA','Devana','Slavic','goddess','Hunt goddess','the hunt; wild nature; the forest','C','A goddess of the hunt (Dziewanna) named by late-medieval Polish chroniclers (Długosz) who equated her with Diana; authenticity debated as a possible learned interpretatio.'),
 ('ENT_SLAV_DOMOVOI','Domovoi','Slavic','folk spirit','Household spirit','household; hearth; family protection','A','The tutelary house spirit of East-Slavic folk belief, dwelling behind the stove and protecting the household and its livestock if respected.'),
 ('ENT_SLAV_RUSALKA','Rusalka','Slavic','folk spirit','Water nymph','water; rivers; the unquiet drowned dead','A','A female water spirit, commonly the restless soul of a drowned or unbaptized woman, who haunts rivers and woods especially during Rusalka Week.'),
 ('ENT_SLAV_LESHY','Leshy','Slavic','folk spirit','Forest spirit','forest; wild animals; the woods','A','The master spirit of the forest in East-Slavic belief, who guards the woodland and its animals and is known for leading travelers astray.'),
 ('ENT_SLAV_VODYANOY','Vodyanoy','Slavic','folk spirit','Water spirit','water; rivers; lakes; drowning','A','A malevolent male water spirit of East-Slavic folklore who rules ponds and rivers and is blamed for drownings.'),
 ('ENT_SLAV_KIKIMORA','Kikimora','Slavic','folk spirit','Household spirit','household; spinning; nocturnal disturbance','B','A female household spirit associated with the stove and spinning, who troubles a disorderly home with nighttime noises.'),
 ('ENT_SLAV_BANNIK','Bannik','Slavic','folk spirit','Bathhouse spirit','the bathhouse; divination; ritual purity','B','The spirit of the bathhouse (banya) in East-Slavic belief, who must be appeased and can scald bathers who offend him.'),
 ('ENT_SLAV_POLEVIK','Polevik','Slavic','folk spirit','Field spirit','fields; crops; the harvest','B','A field spirit who inhabits cultivated land and may help or punish field-workers, especially those who sleep in the fields at midday.'),
 ('ENT_SLAV_BABA_YAGA','Baba Yaga','Slavic','witch','Folktale witch','witchcraft; the forest; initiation; the death-threshold','A','The ambivalent witch of East-Slavic folktales who lives in a hut on hen''s legs, flies in a mortar, and acts as both threat and helper to the hero.'),
 ('ENT_SLAV_KOSCHEI','Koschei the Deathless','Slavic','monster','Folktale antagonist','death-evasion; abduction; sorcery','A','An immortal sorcerer-villain of East-Slavic folktales who abducts the hero''s bride and cannot die because his death is hidden in a needle inside an egg.'),
 ('ENT_SLAV_ZMEY_GORYNYCH','Zmey Gorynych','Slavic','dragon','Folktale dragon','fire; chaos; the dragon-slaying combat','A','The multi-headed fire-breathing dragon of East-Slavic byliny and folktales, slain by heroes such as Dobrynya Nikitich.'),
 ('ENT_FINN_PANTHEON','The Finnish/Kalevala Pantheon','Finnish','Collective','Pantheon','Finnic mythology; deities and heroes of the Kalevala and Agricola''s deity list','A','Collective grouping of the gods, heroes, and otherworld powers of Finnic tradition as preserved in the Kalevala and Agricola''s 1551 deity list.'),
 ('ENT_FINN_ILMARINEN','Ilmarinen','Finnish','god','Smith god / culture hero','smithing; metalworking; weather; fire','A','The eternal smith of the Kalevala who hammered out the dome of the sky and forged the Sampo, the magical mill of plenty, for Louhi of Pohjola.'),
 ('ENT_FINN_LEMMINKAINEN','Lemminkäinen','Finnish','hero','Culture hero / shaman','war; seduction; magic; recklessness','A','A reckless, amorous warrior-shaman of the Kalevala who is slain and dismembered at the river of Tuonela and revived by his mother.'),
 ('ENT_FINN_VELLAMO','Vellamo','Finnish','goddess','Sea goddess','sea; water; fish','A','Goddess of the sea and waters, wife of Ahti, who keeps the fish and is invoked by fishermen in the Kalevala.'),
 ('ENT_FINN_TUONI','Tuoni','Finnish','god','Death god / underworld ruler','death; the underworld','A','Lord of the dead who rules Tuonela, the dark land of the dead reached across the river of Tuoni.'),
 ('ENT_FINN_TUONETAR','Tuonetar','Finnish','goddess','Death goddess / underworld queen','death; the underworld','B','Queen of the dead and consort of Tuoni, mistress of the household of Tuonela who serves the dead the drink of the underworld.'),
 ('ENT_FINN_KULLERVO','Kullervo','Finnish','hero','Tragic hero','vengeance; fate; ruin','A','The doomed orphan-slave of the Kalevala whose vengeance and unwitting incest end in his suicide upon his own sword.'),
 ('ENT_FINN_PELLERVO','Pellervo (Sampsa)','Finnish','god','Vegetation / sowing god','vegetation; sowing; agriculture; fertility of fields','B','Sampsa Pellervoinen, the sower-spirit of the Kalevala who scatters seed and makes the trees and crops grow over the land.'),
 ('ENT_FINN_NYYRIKKI','Nyyrikki','Finnish','god','Forest god','forest; hunting; game','B','Forest god, son of Tapio, who guides hunters and marks the paths of game through the woods.'),
 ('ENT_FINN_TELLERVO','Tellervo','Finnish','goddess','Forest spirit','forest; woodland creatures','B','Maiden of the forest, daughter of Tapio, who herds and protects the cattle and game of the woodland.'),
 ('ENT_FINN_KALMA','Kalma','Finnish','spirit','Death / decay personification','death; decay; the grave','B','Personification of death and the stench of decay, associated with graves and the rotting corpse in Finnic tradition.'),
 ('ENT_FINN_HIISI','Hiisi','Finnish','monster','Malevolent forest demon','wilderness; malevolence; disease; dangerous places','B','A malevolent forest demon (and the dangerous sacred grove it haunts), named in Agricola''s deity list and the Kalevala as a source of evil and disease.'),
 ('ENT_FINN_SURMA','Surma','Finnish','spirit','Death personification','violent death; sudden death','C','Personification of violent or sudden death, a monstrous gatekeeping power associated with the threshold of Tuonela.'),
 ('ENT_FINN_PEKKO','Pellon Pekko (Pekko)','Finnish','god','Crop / barley god','barley; crops; brewing; agriculture','B','God of barley and the fields named in Agricola''s list (Pellon Pekko), invoked for the growth of grain and the making of beer.'),
 ('ENT_FINN_RAUNI','Rauni','Finnish','goddess','Fertility goddess / consort','fertility; thunder; harvest','C','An obscure figure from Agricola''s list traditionally read as the consort of the thunder-god Ukko, associated with fertility and the harvest.'),
 ('ENT_FINN_TUONELA','Tuonela','Finnish','cosmological realm','Underworld / land of the dead','the underworld; the dead','A','The land of the dead in Finnic cosmology, ruled by Tuoni and Tuonetar and separated from the living by the dark river of Tuoni.'),
 ('ENT_FINN_POHJOLA','Pohjola','Finnish','cosmological realm','Otherworld / northern land','the far north; the otherworld; cold and darkness','A','The dark northern otherworld of the Kalevala, ruled by Louhi, where the Sampo was forged and hidden inside a copper mountain.'),
 ('ENT_BALT_PANTHEON','The Baltic Pantheon','Baltic','Collective','Pantheon','Baltic mythology; Lithuanian, Latvian, and Prussian deities and spirits','A','Collective grouping of the deities and spirits of the Baltic peoples (Lithuanian, Latvian, Old Prussian) as reconstructed by Gimbutas and Greimas from folklore and medieval chronicles.'),
 ('ENT_BALT_AUSRINE','Aušrinė / Auseklis','Baltic','goddess','Morning-star deity','the morning star (Venus); dawn; light','A','The morning star personified, Lithuanian Aušrinė (a goddess, daughter of the sun Saulė) and Latvian Auseklis (a male morning-star figure of the daina songs).'),
 ('ENT_BALT_USINS','Ūsiņš','Baltic','god','Horse / light god','horses; bees; light; spring; fertility','B','Latvian god of horses, bees, and the returning light of spring, celebrated at the festival marking the start of pasturing.'),
 ('ENT_BALT_BANGPUTYS','Bangpūtys','Baltic','god','Sea / storm god','sea; storms; waves; wind','B','Lithuanian god of the sea and storm winds, the ''wave-blower'' who raises the waves and is appeased by Baltic-coast fishermen.'),
 ('ENT_BALT_POTRIMPO','Potrimpo','Baltic','god','Water / grain god','rivers and waters; grain; fertility; good fortune','B','Old Prussian god of running waters and grain, one of the triad on the banner of Romuva, associated with fertility and good fortune.'),
 ('ENT_BALT_PATULAS','Patulas (Pikuolis)','Baltic','god','Death / underworld god','death; the underworld; night; evil','B','Old Prussian god of the dead and the underworld (Patulas/Pikuolis/Pecols), the third of the Romuva triad, lord of night and darkness.'),
 ('ENT_BALT_MATES','The Mātes (the Latvian Mothers)','Baltic','Collective','Domain-mother goddesses','tutelary motherhood of natural domains (forest, sea, earth, wind, fields)','A','The many Latvian ''mother'' goddesses (Mātes), each presiding over a natural domain, attested in the dainas as Meža māte, Jūras māte, Zemes māte, Vēja māte, and dozens more.'),
 ('ENT_BALT_JURASMATE','Jūras māte (Mother of the Sea)','Baltic','goddess','Sea-mother goddess','the sea; waters','A','The Latvian ''Mother of the Sea'', a tutelary goddess of the waters and one of the most prominent of the Mātes in the daina folk songs.'),
 ('ENT_BALT_AITVARAS','Aitvaras','Baltic','spirit','Household / wealth spirit','household wealth; theft of goods; fire; fortune','A','Lithuanian household serpent or flying drake that brings stolen wealth (grain, milk, gold) to the home it favors, appearing as a fiery flying creature.'),
 ('ENT_BALT_KAUKAS','Kaukas','Baltic','spirit','Household / domestic spirit','household; hearth; prosperity of the farm','A','Lithuanian household spirit, a small chthonic being that guards the homestead and brings prosperity if honored, named alongside the barstukai.'),
 ('ENT_BSQ_PANTHEON','Basque Pantheon','Basque','Collective','Pantheon','polytheistic pantheon; Basque folk religion','B','Collective grouping the pre-Christian Basque mythological beings reconstructed chiefly from oral tradition by José Miguel de Barandiarán in his Mitología Vasca.'),
 ('ENT_BSQ_MARI','Mari','Basque','goddess','Deity','weather; mountains; earth; sovereignty','B','Supreme goddess of Basque mythology, lady of the mountains who dwells in caves and governs storms, hail and the weather.'),
 ('ENT_BSQ_SUGAAR','Sugaar (Sugoi)','Basque','serpent','Deity','serpents; storms; lightning','B','Male serpent or dragon spirit, the consort of Mari, associated with thunder and storms; also called Sugoi or Maju.'),
 ('ENT_BSQ_MAIRU','Mairu','Basque','giant','Mythic being','megalith-building; wilderness','B','Race of giants of Basque legend held to have built the dolmens and stone megaliths (mairubaratza).'),
 ('ENT_BSQ_BASAJAUN','Basajaun','Basque','spirit','Mythic being','forests; wild nature; flocks; agriculture','B','The ''lord of the woods'', a hairy wild-man spirit credited in legend with teaching agriculture and ironwork to humans.'),
 ('ENT_BSQ_BASANDERE','Basandere','Basque','spirit','Mythic being','forests; wild nature','B','The ''lady of the woods'', female counterpart of Basajaun in Basque forest mythology.'),
 ('ENT_BSQ_GAUEKO','Gaueko','Basque','spirit','Mythic being','night; darkness','B','Genius or spirit of the night who enforces that the night belongs to him and the day to humans.'),
 ('ENT_BSQ_EATE','Eate','Basque','spirit','Mythic being','storms; fire; floods','C','Storm and fire spirit announcing tempests and floods; sparsely attested in the Basque oral record.'),
 ('ENT_BSQ_TARTALO','Tartalo','Basque','giant','Mythic being','wilderness; man-eating','B','One-eyed man-eating giant of Basque folklore, a Cyclops-type figure paralleling the Greek Polyphemus motif.'),
 ('ENT_BSQ_LAMIA','Lamia (Lamiak)','Basque','nymph','Mythic being','rivers; springs; waters','B','Female water spirits of rivers and springs, typically depicted with the feet of birds or fish.'),
 ('ENT_BSQ_URTZI','Urtzi (Ortzi)','Basque','god','Deity','sky; firmament','C','DISPUTED: the word ortzi/urtzi denotes the sky/firmament and appears in weather compounds; whether it ever named a personified sky-god is contested.'),
 ('ENT_SAMI_PANTHEON','Sámi Pantheon','Sámi','Collective','Pantheon','polytheistic pantheon; Sámi pre-Christian religion','B','Collective grouping the deities and spirits of the pre-Christian Sámi noaidi religion of Fennoscandia.'),
 ('ENT_SAMI_HORAGALLES','Horagalles','Sámi','god','Deity','thunder; lightning; sky; protection','B','Thunder god of the Sámi, his name derived from ''Thor-karl'' (Old Thor) and widely held to be a borrowing of the Norse Thor.'),
 ('ENT_SAMI_BEAIVI','Beaivi','Sámi','deity','Deity','sun; light; fertility; sanity','B','Sun deity of the Sámi, source of light, fertility of reindeer and crops, and of mental health; gender varies across sources.'),
 ('ENT_SAMI_MANNU','Mánnu','Sámi','deity','Deity','moon; night','C','Personification of the moon in Sámi belief; comparatively lightly attested relative to the sun.'),
 ('ENT_SAMI_RADIEN_ATTJE','Radien-attje','Sámi','god','Deity','creation; sky; world order','B','The high creator-father of the southern Sámi cosmology, a remote sky-ruler who delegates active rule.'),
 ('ENT_SAMI_RADIEN_AKKA','Radien-akka','Sámi','goddess','Deity','creation; consort of the high god','B','Female consort of Radien-attje in the southern Sámi creator-pair cosmology.'),
 ('ENT_SAMI_MATTARAHKKA','Máttaráhkká','Sámi','goddess','Deity','motherhood; birth; household; fertility','B','The great mother-goddess of the Sámi who receives the soul of the child and presides over birth, mother of the three áhkká household goddesses.'),
 ('ENT_SAMI_SARAHKKA','Sáráhkká','Sámi','goddess','Deity','childbirth; menstruation; the hearth','B','Daughter of Máttaráhkká and the most venerated áhkká goddess, who aids women in menstruation and childbirth and dwells beneath the hearth.'),
 ('ENT_SAMI_JUOKSAHKKA','Juoksáhkká','Sámi','goddess','Deity','male children; hunting; the bow','B','Daughter of Máttaráhkká, the ''bow-woman'' who turns a child male and protects boys and hunters.'),
 ('ENT_SAMI_UKSAHKKA','Uksáhkká','Sámi','goddess','Deity','the doorway; infants; household protection','B','Daughter of Máttaráhkká, the ''door-woman'' who dwells by the threshold and guards the newborn child.'),
 ('ENT_SAMI_LEIBOLMAI','Leib-olmai','Sámi','god','Deity','bears; hunting; the hunt','B','The ''alder-man'' or bear-and-hunt god whose favour was sought for success in the hunt, especially the bear hunt.'),
 ('ENT_SAMI_STALLO','Stallo','Sámi','ogre','Mythic being','man-eating; wilderness; menace','B','Stupid, man-eating ogre of Sámi folklore who pursues humans but is regularly outwitted; a folkloric rather than cultic figure.'),
 ('ENT_SAMI_BIEGGOLMAI','Bieggolmai','Sámi','god','Deity','wind; weather; storms','B','The ''wind-man'' who governs the winds and storms with his two shovels, raising and stilling the weather.'),
 ('ENT_HUN_PANTHEON','Hungarian (Magyar) Pantheon','Hungarian','Collective','Pantheon','pre-Christian Magyar religion; reconstructed mythology','C','Collective grouping the figures of pre-Christian Magyar religion, largely a scholarly reconstruction from folklore, loanwords, and comparison since few pagan sources survive.'),
 ('ENT_HUN_ISTEN','Isten','Hungarian','god','Deity','sky; supreme deity; creation','B','Supreme sky-god of the pagan Magyars whose name was retained as the ordinary Hungarian word for ''God'' after Christianization.'),
 ('ENT_HUN_ORDOG','Ördög','Hungarian','spirit','Deity','the underworld; evil; adversary','B','The adversary and spirit of the underworld and evil in Magyar belief, the dark counterpart to Isten, later identified with the Christian Devil.'),
 ('ENT_HUN_BOLDOGASSZONY','Boldogasszony','Hungarian','goddess','Deity','motherhood; childbirth; fertility; protection','C','Reconstructed great mother-goddess (''Blessed Lady'') of the pagan Magyars, whose cult was assimilated to the Virgin Mary after Christianization.'),
 ('ENT_HUN_NAGYBOLDOGASSZONY','Nagyboldogasszony','Hungarian','goddess','Deity','motherhood; ancestral mother; fertility','C','The ''Great Blessed Lady'', a grand or ancestral mother-goddess of reconstructed Magyar religion, later folded into Marian veneration of the Assumption.'),
 ('ENT_HUN_TURUL','Turul','Hungarian','spirit','Mythic being','origin myth; dynastic protection; the heavens','B','Mythic falcon or bird of prey of the Magyar origin myth, ancestral protector of the Árpád dynasty as recorded in the medieval chronicles.'),
 ('ENT_HUN_VILAGFA','Életfa / Világfa (World-Tree)','Hungarian','world-tree','Cosmological realm','axis mundi; cosmology; the three worlds','C','The ''tree of life'' or ''world-tree'' connecting the upper, middle, and lower worlds in reconstructed Magyar shamanic cosmology, the path of the táltos.'),
 ('ENT_HUN_TALTOS','Táltos','Hungarian','Collective','Religious class','shamanism; prophecy; healing; spirit-journey','B','Class of Magyar shaman-seers, born with bodily marks, who entered trance to journey between worlds, heal, and divine; modeled here as a collective class.'),
 ('ENT_HUN_HADUR','Hadúr','Hungarian','god','Deity','war; metalworking; fire','C','RECONSTRUCTED: ''War-lord'' war-god, largely a 19th-century Romantic-era literary creation rather than a securely attested pagan deity.');
INSERT INTO entities (entity_id,canonical_name,tradition,entity_type,category,primary_domains,cult_scope,evidence_confidence,review_status,inclusion_basis,earth_association_score,chthonic_flag,serpent_flag,short_note)
INSERT INTO _s VALUES
 ('ENT_SLAV_PANTHEON','SRC_BRUCKNER_SLAVIC_MYTH','Collective grouping the principal deities of the Slavs known from the East-Slavic Primary Chronicle and the West-Slavic temple cults of Arkona, Szczecin, and Rethra.','scholarly attestation'),
 ('ENT_SLAV_FOLK_SPIRITS','SRC_BRUCKNER_SLAVIC_MYTH','Collective of lower mythological beings of East-Slavic folk belief (house, water, forest, and field spirits) documented in the ethnographic record.','scholarly attestation'),
 ('ENT_SLAV_SVETOVIT','SRC_SAXO_GESTA','The four-headed chief god of the great temple at Arkona on Rügen, whose white-horse oracle Saxo Grammaticus describes before the temple''s destruction in 1168.','primary text attestation'),
 ('ENT_SLAV_TRIGLAV','SRC_HELMOLD_CHRONICA','The three-headed god of Szczecin and Wolin whose heads signified rule over heaven, earth, and the underworld, reported in the Lives of Otto of Bamberg.','primary text attestation'),
 ('ENT_SLAV_RUGIEVIT','SRC_SAXO_GESTA','A seven-faced war god of the Rani at Charenza (Garz) on Rügen, whose oaken idol Saxo describes being destroyed in 1168.','primary text attestation'),
 ('ENT_SLAV_POREVIT','SRC_SAXO_GESTA','A five-headed god of the Rani worshipped alongside Rugievit at Charenza on Rügen, known only from Saxo; his specific functions are unrecorded.','primary text attestation'),
 ('ENT_SLAV_PORENUT','SRC_SAXO_GESTA','A god of the Rani at Charenza on Rügen described by Saxo as having four faces with a fifth on his chest; his functions are unrecorded.','primary text attestation'),
 ('ENT_SLAV_YAROVIT','SRC_HELMOLD_CHRONICA','A West-Slavic war god (Latinized Gerovitus) worshipped at Wolgast and Havelberg, equated with Mars and associated with spring fertility.','primary text attestation'),
 ('ENT_SLAV_RADEGAST','SRC_HELMOLD_CHRONICA','The chief god of the Redarii at the temple of Rethra, named by Helmold and Adam of Bremen; often identified by scholars with Svarozhich.','primary text attestation'),
 ('ENT_SLAV_ZHIVA','SRC_HELMOLD_CHRONICA','A goddess of the Polabian Slavs (Siwa/Živa) named by Helmold, her name connected to the Slavic root for ''living'', suggesting a life/fertility function.','primary text attestation'),
 ('ENT_SLAV_CHERNOBOG','SRC_HELMOLD_CHRONICA','The ''black god'' of the Polabian Slavs to whom Helmold says misfortune was attributed; the only securely attested member of the often-cited black/white dualism.','primary text attestation'),
 ('ENT_SLAV_BELOBOG','SRC_BRUCKNER_SLAVIC_MYTH','RECONSTRUCTED: the ''white god'' posited as a benevolent counterpart to Chernobog; not attested in any medieval source, a scholarly/toponymic inference.','scholarly attestation'),
 ('ENT_SLAV_SVAROZHICH','SRC_HELMOLD_CHRONICA','A fire god understood as the son of Svarog; chief deity of the temple at Rethra in the West-Slavic chronicles and the personified sacred fire in East-Slavic homilies.','primary text attestation'),
 ('ENT_SLAV_ROZHANITSY','SRC_BRUCKNER_SLAVIC_MYTH','Female birth-and-fate spirits invoked together with Rod, repeatedly condemned in medieval East-Slavic anti-pagan homilies for childbirth offerings.','scholarly attestation'),
 ('ENT_SLAV_DOLA','SRC_BRUCKNER_SLAVIC_MYTH','The personification of an individual''s allotted fate or fortune in Slavic folk belief, attached at birth; its negative counterpart is Nedola.','scholarly attestation'),
 ('ENT_SLAV_MARZANNA','SRC_BRUCKNER_SLAVIC_MYTH','Goddess or personification of death and winter (Morana/Morena), whose effigy is ritually drowned or burned at winter''s end in Slavic seasonal custom.','scholarly attestation'),
 ('ENT_SLAV_JARILO','SRC_BRUCKNER_SLAVIC_MYTH','A spring fertility figure of the seasonal folk cult whose effigy was carried and ritually ''buried'', reconstructed as the dying-and-rising counterpart to Marzanna.','scholarly attestation'),
 ('ENT_SLAV_KUPALA','SRC_BRUCKNER_SLAVIC_MYTH','The personification of the midsummer (St John''s Eve) festival of fire and water; treated in some sources as a folk personification of the rite.','scholarly attestation'),
 ('ENT_SLAV_LADA','SRC_BRUCKNER_SLAVIC_MYTH','DISPUTED: a putative goddess of love and marriage; Brückner and later scholarship argue she is a personification mistakenly derived from a wedding-song refrain (''lado'').','scholarly attestation'),
 ('ENT_SLAV_DEVANA','SRC_BRUCKNER_SLAVIC_MYTH','A goddess of the hunt (Dziewanna) named by late-medieval Polish chroniclers (Długosz) who equated her with Diana; authenticity debated as a possible learned interpretatio.','scholarly attestation'),
 ('ENT_SLAV_DOMOVOI','SRC_BRUCKNER_SLAVIC_MYTH','The tutelary house spirit of East-Slavic folk belief, dwelling behind the stove and protecting the household and its livestock if respected.','scholarly attestation'),
 ('ENT_SLAV_RUSALKA','SRC_BRUCKNER_SLAVIC_MYTH','A female water spirit, commonly the restless soul of a drowned or unbaptized woman, who haunts rivers and woods especially during Rusalka Week.','scholarly attestation'),
 ('ENT_SLAV_LESHY','SRC_BRUCKNER_SLAVIC_MYTH','The master spirit of the forest in East-Slavic belief, who guards the woodland and its animals and is known for leading travelers astray.','scholarly attestation'),
 ('ENT_SLAV_VODYANOY','SRC_BRUCKNER_SLAVIC_MYTH','A malevolent male water spirit of East-Slavic folklore who rules ponds and rivers and is blamed for drownings.','scholarly attestation'),
 ('ENT_SLAV_KIKIMORA','SRC_BRUCKNER_SLAVIC_MYTH','A female household spirit associated with the stove and spinning, who troubles a disorderly home with nighttime noises.','scholarly attestation'),
 ('ENT_SLAV_BANNIK','SRC_BRUCKNER_SLAVIC_MYTH','The spirit of the bathhouse (banya) in East-Slavic belief, who must be appeased and can scald bathers who offend him.','scholarly attestation'),
 ('ENT_SLAV_POLEVIK','SRC_BRUCKNER_SLAVIC_MYTH','A field spirit who inhabits cultivated land and may help or punish field-workers, especially those who sleep in the fields at midday.','scholarly attestation'),
 ('ENT_SLAV_BABA_YAGA','SRC_BRUCKNER_SLAVIC_MYTH','The ambivalent witch of East-Slavic folktales who lives in a hut on hen''s legs, flies in a mortar, and acts as both threat and helper to the hero.','scholarly attestation'),
 ('ENT_SLAV_KOSCHEI','SRC_BRUCKNER_SLAVIC_MYTH','An immortal sorcerer-villain of East-Slavic folktales who abducts the hero''s bride and cannot die because his death is hidden in a needle inside an egg.','scholarly attestation'),
 ('ENT_SLAV_ZMEY_GORYNYCH','SRC_BRUCKNER_SLAVIC_MYTH','The multi-headed fire-breathing dragon of East-Slavic byliny and folktales, slain by heroes such as Dobrynya Nikitich.','scholarly attestation'),
 ('ENT_FINN_PANTHEON','SRC_KALEVALA','Collective grouping of the gods, heroes, and otherworld powers of Finnic tradition as preserved in the Kalevala and Agricola''s 1551 deity list.','primary text attestation'),
 ('ENT_FINN_ILMARINEN','SRC_KALEVALA','The eternal smith of the Kalevala who hammered out the dome of the sky and forged the Sampo, the magical mill of plenty, for Louhi of Pohjola.','primary text attestation'),
 ('ENT_FINN_LEMMINKAINEN','SRC_KALEVALA','A reckless, amorous warrior-shaman of the Kalevala who is slain and dismembered at the river of Tuonela and revived by his mother.','primary text attestation'),
 ('ENT_FINN_VELLAMO','SRC_KALEVALA','Goddess of the sea and waters, wife of Ahti, who keeps the fish and is invoked by fishermen in the Kalevala.','primary text attestation'),
 ('ENT_FINN_TUONI','SRC_KALEVALA','Lord of the dead who rules Tuonela, the dark land of the dead reached across the river of Tuoni.','primary text attestation'),
 ('ENT_FINN_TUONETAR','SRC_KALEVALA','Queen of the dead and consort of Tuoni, mistress of the household of Tuonela who serves the dead the drink of the underworld.','primary text attestation'),
 ('ENT_FINN_KULLERVO','SRC_KALEVALA','The doomed orphan-slave of the Kalevala whose vengeance and unwitting incest end in his suicide upon his own sword.','primary text attestation'),
 ('ENT_FINN_PELLERVO','SRC_KALEVALA','Sampsa Pellervoinen, the sower-spirit of the Kalevala who scatters seed and makes the trees and crops grow over the land.','primary text attestation'),
 ('ENT_FINN_NYYRIKKI','SRC_KALEVALA','Forest god, son of Tapio, who guides hunters and marks the paths of game through the woods.','primary text attestation'),
 ('ENT_FINN_TELLERVO','SRC_KALEVALA','Maiden of the forest, daughter of Tapio, who herds and protects the cattle and game of the woodland.','primary text attestation'),
 ('ENT_FINN_KALMA','SRC_KALEVALA','Personification of death and the stench of decay, associated with graves and the rotting corpse in Finnic tradition.','primary text attestation'),
 ('ENT_FINN_HIISI','SRC_AGRICOLA_PRIMER','A malevolent forest demon (and the dangerous sacred grove it haunts), named in Agricola''s deity list and the Kalevala as a source of evil and disease.','primary text attestation'),
 ('ENT_FINN_SURMA','SRC_KALEVALA','Personification of violent or sudden death, a monstrous gatekeeping power associated with the threshold of Tuonela.','primary text attestation'),
 ('ENT_FINN_PEKKO','SRC_AGRICOLA_PRIMER','God of barley and the fields named in Agricola''s list (Pellon Pekko), invoked for the growth of grain and the making of beer.','primary text attestation'),
 ('ENT_FINN_RAUNI','SRC_AGRICOLA_PRIMER','An obscure figure from Agricola''s list traditionally read as the consort of the thunder-god Ukko, associated with fertility and the harvest.','primary text attestation'),
 ('ENT_FINN_TUONELA','SRC_KALEVALA','The land of the dead in Finnic cosmology, ruled by Tuoni and Tuonetar and separated from the living by the dark river of Tuoni.','primary text attestation'),
 ('ENT_FINN_POHJOLA','SRC_KALEVALA','The dark northern otherworld of the Kalevala, ruled by Louhi, where the Sampo was forged and hidden inside a copper mountain.','primary text attestation'),
 ('ENT_BALT_PANTHEON','SRC_GIMBUTAS_BALTS','Collective grouping of the deities and spirits of the Baltic peoples (Lithuanian, Latvian, Old Prussian) as reconstructed by Gimbutas and Greimas from folklore and medieval chronicles.','scholarly attestation'),
 ('ENT_BALT_AUSRINE','SRC_GREIMAS_LITHUANIAN','The morning star personified, Lithuanian Aušrinė (a goddess, daughter of the sun Saulė) and Latvian Auseklis (a male morning-star figure of the daina songs).','scholarly attestation'),
 ('ENT_BALT_USINS','SRC_GIMBUTAS_BALTS','Latvian god of horses, bees, and the returning light of spring, celebrated at the festival marking the start of pasturing.','scholarly attestation'),
 ('ENT_BALT_BANGPUTYS','SRC_GREIMAS_LITHUANIAN','Lithuanian god of the sea and storm winds, the ''wave-blower'' who raises the waves and is appeased by Baltic-coast fishermen.','scholarly attestation'),
 ('ENT_BALT_POTRIMPO','SRC_GIMBUTAS_BALTS','Old Prussian god of running waters and grain, one of the triad on the banner of Romuva, associated with fertility and good fortune.','scholarly attestation'),
 ('ENT_BALT_PATULAS','SRC_GIMBUTAS_BALTS','Old Prussian god of the dead and the underworld (Patulas/Pikuolis/Pecols), the third of the Romuva triad, lord of night and darkness.','scholarly attestation'),
 ('ENT_BALT_MATES','SRC_GIMBUTAS_BALTS','The many Latvian ''mother'' goddesses (Mātes), each presiding over a natural domain, attested in the dainas as Meža māte, Jūras māte, Zemes māte, Vēja māte, and dozens more.','scholarly attestation'),
 ('ENT_BALT_JURASMATE','SRC_GIMBUTAS_BALTS','The Latvian ''Mother of the Sea'', a tutelary goddess of the waters and one of the most prominent of the Mātes in the daina folk songs.','scholarly attestation'),
 ('ENT_BALT_AITVARAS','SRC_GREIMAS_LITHUANIAN','Lithuanian household serpent or flying drake that brings stolen wealth (grain, milk, gold) to the home it favors, appearing as a fiery flying creature.','scholarly attestation'),
 ('ENT_BALT_KAUKAS','SRC_GREIMAS_LITHUANIAN','Lithuanian household spirit, a small chthonic being that guards the homestead and brings prosperity if honored, named alongside the barstukai.','scholarly attestation'),
 ('ENT_BSQ_PANTHEON','SRC_BARANDIARAN','Collective grouping the pre-Christian Basque mythological beings reconstructed chiefly from oral tradition by José Miguel de Barandiarán in his Mitología Vasca.','scholarly attestation'),
 ('ENT_BSQ_MARI','SRC_BARANDIARAN','Supreme goddess of Basque mythology, lady of the mountains who dwells in caves and governs storms, hail and the weather.','scholarly attestation'),
 ('ENT_BSQ_SUGAAR','SRC_BARANDIARAN','Male serpent or dragon spirit, the consort of Mari, associated with thunder and storms; also called Sugoi or Maju.','scholarly attestation'),
 ('ENT_BSQ_MAIRU','SRC_BARANDIARAN','Race of giants of Basque legend held to have built the dolmens and stone megaliths (mairubaratza).','scholarly attestation'),
 ('ENT_BSQ_BASAJAUN','SRC_BARANDIARAN','The ''lord of the woods'', a hairy wild-man spirit credited in legend with teaching agriculture and ironwork to humans.','scholarly attestation'),
 ('ENT_BSQ_BASANDERE','SRC_BARANDIARAN','The ''lady of the woods'', female counterpart of Basajaun in Basque forest mythology.','scholarly attestation'),
 ('ENT_BSQ_GAUEKO','SRC_BARANDIARAN','Genius or spirit of the night who enforces that the night belongs to him and the day to humans.','scholarly attestation'),
 ('ENT_BSQ_EATE','SRC_BARANDIARAN','Storm and fire spirit announcing tempests and floods; sparsely attested in the Basque oral record.','scholarly attestation'),
 ('ENT_BSQ_TARTALO','SRC_BARANDIARAN','One-eyed man-eating giant of Basque folklore, a Cyclops-type figure paralleling the Greek Polyphemus motif.','scholarly attestation'),
 ('ENT_BSQ_LAMIA','SRC_BARANDIARAN','Female water spirits of rivers and springs, typically depicted with the feet of birds or fish.','scholarly attestation'),
 ('ENT_BSQ_URTZI','SRC_BARANDIARAN','DISPUTED: the word ortzi/urtzi denotes the sky/firmament and appears in weather compounds; whether it ever named a personified sky-god is contested.','scholarly attestation'),
 ('ENT_SAMI_PANTHEON','SRC_SAMI_RELIGION','Collective grouping the deities and spirits of the pre-Christian Sámi noaidi religion of Fennoscandia.','scholarly attestation'),
 ('ENT_SAMI_HORAGALLES','SRC_SAMI_RELIGION','Thunder god of the Sámi, his name derived from ''Thor-karl'' (Old Thor) and widely held to be a borrowing of the Norse Thor.','scholarly attestation'),
 ('ENT_SAMI_BEAIVI','SRC_SAMI_RELIGION','Sun deity of the Sámi, source of light, fertility of reindeer and crops, and of mental health; gender varies across sources.','scholarly attestation'),
 ('ENT_SAMI_MANNU','SRC_SAMI_RELIGION','Personification of the moon in Sámi belief; comparatively lightly attested relative to the sun.','scholarly attestation'),
 ('ENT_SAMI_RADIEN_ATTJE','SRC_SAMI_RELIGION','The high creator-father of the southern Sámi cosmology, a remote sky-ruler who delegates active rule.','scholarly attestation'),
 ('ENT_SAMI_RADIEN_AKKA','SRC_SAMI_RELIGION','Female consort of Radien-attje in the southern Sámi creator-pair cosmology.','scholarly attestation'),
 ('ENT_SAMI_MATTARAHKKA','SRC_SAMI_RELIGION','The great mother-goddess of the Sámi who receives the soul of the child and presides over birth, mother of the three áhkká household goddesses.','scholarly attestation'),
 ('ENT_SAMI_SARAHKKA','SRC_SAMI_RELIGION','Daughter of Máttaráhkká and the most venerated áhkká goddess, who aids women in menstruation and childbirth and dwells beneath the hearth.','scholarly attestation'),
 ('ENT_SAMI_JUOKSAHKKA','SRC_SAMI_RELIGION','Daughter of Máttaráhkká, the ''bow-woman'' who turns a child male and protects boys and hunters.','scholarly attestation'),
 ('ENT_SAMI_UKSAHKKA','SRC_SAMI_RELIGION','Daughter of Máttaráhkká, the ''door-woman'' who dwells by the threshold and guards the newborn child.','scholarly attestation'),
 ('ENT_SAMI_LEIBOLMAI','SRC_SAMI_RELIGION','The ''alder-man'' or bear-and-hunt god whose favour was sought for success in the hunt, especially the bear hunt.','scholarly attestation'),
 ('ENT_SAMI_STALLO','SRC_SAMI_RELIGION','Stupid, man-eating ogre of Sámi folklore who pursues humans but is regularly outwitted; a folkloric rather than cultic figure.','scholarly attestation'),
 ('ENT_SAMI_BIEGGOLMAI','SRC_SAMI_RELIGION','The ''wind-man'' who governs the winds and storms with his two shovels, raising and stilling the weather.','scholarly attestation'),
 ('ENT_HUN_PANTHEON','SRC_HUNGARIAN_MYTH','Collective grouping the figures of pre-Christian Magyar religion, largely a scholarly reconstruction from folklore, loanwords, and comparison since few pagan sources survive.','scholarly attestation'),
 ('ENT_HUN_ISTEN','SRC_HUNGARIAN_MYTH','Supreme sky-god of the pagan Magyars whose name was retained as the ordinary Hungarian word for ''God'' after Christianization.','scholarly attestation'),
 ('ENT_HUN_ORDOG','SRC_HUNGARIAN_MYTH','The adversary and spirit of the underworld and evil in Magyar belief, the dark counterpart to Isten, later identified with the Christian Devil.','scholarly attestation'),
 ('ENT_HUN_BOLDOGASSZONY','SRC_HUNGARIAN_MYTH','Reconstructed great mother-goddess (''Blessed Lady'') of the pagan Magyars, whose cult was assimilated to the Virgin Mary after Christianization.','scholarly attestation'),
 ('ENT_HUN_NAGYBOLDOGASSZONY','SRC_HUNGARIAN_MYTH','The ''Great Blessed Lady'', a grand or ancestral mother-goddess of reconstructed Magyar religion, later folded into Marian veneration of the Assumption.','scholarly attestation'),
 ('ENT_HUN_TURUL','SRC_HUNGARIAN_MYTH','Mythic falcon or bird of prey of the Magyar origin myth, ancestral protector of the Árpád dynasty as recorded in the medieval chronicles.','scholarly attestation'),
 ('ENT_HUN_VILAGFA','SRC_HUNGARIAN_MYTH','The ''tree of life'' or ''world-tree'' connecting the upper, middle, and lower worlds in reconstructed Magyar shamanic cosmology, the path of the táltos.','scholarly attestation'),
 ('ENT_HUN_TALTOS','SRC_HUNGARIAN_MYTH','Class of Magyar shaman-seers, born with bodily marks, who entered trance to journey between worlds, heal, and divine; modeled here as a collective class.','scholarly attestation'),
 ('ENT_HUN_HADUR','SRC_HUNGARIAN_MYTH','RECONSTRUCTED: ''War-lord'' war-god, largely a 19th-century Romantic-era literary creation rather than a securely attested pagan deity.','scholarly attestation');
INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_SLAV_PANTHEON','PER_SLAV_PAGAN','Collective grouping the principal deities of the Slavs known from the East-Slavic Primary Chronicle and the West-Slavic temple cults of Arkona, Szczecin, and Rethra.'),
 ('ENT_SLAV_FOLK_SPIRITS','PER_SLAV_PAGAN','Collective of lower mythological beings of East-Slavic folk belief (house, water, forest, and field spirits) documented in the ethnographic record.'),
 ('ENT_SLAV_SVETOVIT','PER_SLAV_PAGAN','The four-headed chief god of the great temple at Arkona on Rügen, whose white-horse oracle Saxo Grammaticus describes before the temple''s destruction in 1168.'),
 ('ENT_SLAV_TRIGLAV','PER_SLAV_PAGAN','The three-headed god of Szczecin and Wolin whose heads signified rule over heaven, earth, and the underworld, reported in the Lives of Otto of Bamberg.'),
 ('ENT_SLAV_RUGIEVIT','PER_SLAV_PAGAN','A seven-faced war god of the Rani at Charenza (Garz) on Rügen, whose oaken idol Saxo describes being destroyed in 1168.'),
 ('ENT_SLAV_POREVIT','PER_SLAV_PAGAN','A five-headed god of the Rani worshipped alongside Rugievit at Charenza on Rügen, known only from Saxo; his specific functions are unrecorded.'),
 ('ENT_SLAV_PORENUT','PER_SLAV_PAGAN','A god of the Rani at Charenza on Rügen described by Saxo as having four faces with a fifth on his chest; his functions are unrecorded.'),
 ('ENT_SLAV_YAROVIT','PER_SLAV_PAGAN','A West-Slavic war god (Latinized Gerovitus) worshipped at Wolgast and Havelberg, equated with Mars and associated with spring fertility.'),
 ('ENT_SLAV_RADEGAST','PER_SLAV_PAGAN','The chief god of the Redarii at the temple of Rethra, named by Helmold and Adam of Bremen; often identified by scholars with Svarozhich.'),
 ('ENT_SLAV_ZHIVA','PER_SLAV_PAGAN','A goddess of the Polabian Slavs (Siwa/Živa) named by Helmold, her name connected to the Slavic root for ''living'', suggesting a life/fertility function.'),
 ('ENT_SLAV_CHERNOBOG','PER_SLAV_PAGAN','The ''black god'' of the Polabian Slavs to whom Helmold says misfortune was attributed; the only securely attested member of the often-cited black/white dualism.'),
 ('ENT_SLAV_BELOBOG','PER_SLAV_PAGAN','RECONSTRUCTED: the ''white god'' posited as a benevolent counterpart to Chernobog; not attested in any medieval source, a scholarly/toponymic inference.'),
